    r: [[{ p: 0.9, t: '你在盐井做了一年工，攒下了一些钱，背也被压弯了。', fx: { cash: 2500, body: -4 } }, { p: 0.1, t: '', fx: { die: 'fall' } }], [{ p: 1, t: '你没有去。', fx: {} }]],
