    q: '番禺港的大船要招水手，去南海诸国贩运香料和象牙，一去一年。', o: ['上船', '不去'],
    r: [[{ p: 0.65, t: '你随船到过许多叫不出名字的国家，回来时带回了一包香料，卖了好价钱。', fx: { cash: 6000, learn: 2 } }, { p: 0.2, t: '船在海上遇了风，货丢了大半，你捡回一条命。', fx: { body: -6 } }, { p: 0.15, t: '', fx: { die: 'drown' } }], [{ p: 1, t: '你没有上船。', fx: {} }]],
