  // 城头易帜时，普通人眼里的改朝换代
  D.WHEEL = {
    palace: ['城头换了旗号。宫门紧闭了好几天，宫人们私下传说，新主进城后会怎样处置旧宫的人。', '宫里换了主人。管事的宦官换了一批，宫人们的名册又重新造了一遍。'],
    poor: ['城头换了旗号。对你家来说，变的只是收租税的人。', '新来的官吏把户口重新清点了一遍，你家又被登记了一次——人头、田亩、牛，一样不落。', '新主下令免了今年一半的田租，乡里人说，这是在收买人心。', '新来的兵在村里征粮，说是"军需"，给你家留下了一张不知能不能兑的木券。', '旧主的告示还贴在亭里，新主的告示就贴在了它上面。不识字的人只看得懂上面的印。', '换了主人之后，过去的欠债、旧年的徭役，没人说得清该不该算数。'],
    merchant: ['城头换了旗号。新主重新定了市租，过关要交的钱又多了一道。', '旧主铸的钱，新主那边不大认，市上的物价又涨了一截。'],
    slave: ['城头换了旗号。主人家关起门来商量了好几天，你们这些奴婢只管烧火做饭。', '主人家派你去城里打听消息。街上的人都在说，换谁来，日子都一样。']
  };

  /* ---------- 家境之差：同是一年，不同人家过的日子 ---------- */
  // 档位：low 赤贫/贫寒，mid 温饱/小康，high 殷实/富足，top 豪富（高门）；奴婢另有一套
  D.TIER_DAILY = {
    child: {
      low: ['冬天你只有一件单衣，和兄弟姐妹轮流穿着出门。', '家里断了粮，母亲把榆树皮剥下来，煮成糊糊。', '你光着脚走了一冬天，脚后跟裂开了好几道口子。', '你跟着母亲去挖野菜，认得了二十几种能吃的草，也认得了几种吃了会死人的。', '你去别人家的地里拾穗，被看田的人赶了出来。', '一年到头，只有过年那天能吃上一顿干饭。', '夜里没有灯油，天一黑全家就睡下了。肚子饿的时候，睡着了就不饿了。', '你看着邻家孩子吃饴糖，咽了好几回口水，没敢开口。', '家里的陶罐裂了，舍不得扔，父亲用麻绳缠起来接着用。', '你和兄弟姐妹睡一张草席，盖一床破絮，冬天夜里冻醒好几回。'],
      mid: ['过年时，母亲给你缝了一件新的短褐。', '腊日杀了一头猪，你分到一块肥肉，香了好几天。', '家里的黄牛下了牛犊，你天天跑去牛棚看它。', '父亲从集上回来，给你带了一个陶哨。', '你家的粟米够吃到来年麦熟，母亲说今年是好年景。', '农闲时，父亲在地上画字教你：一、二、三，田，人。', '你跟着父亲去县城赶集，第一次看见那么多人。', '你和邻家孩子在打谷场上斗草，一直玩到天黑。'],
      high: ['家里雇了长工，农忙时你只需在田边给大人送水。', '父亲请了先生到家里来，教你和堂兄弟们读书。', '你有了一双丝履，舍不得穿，藏在箱子里。', '佃户家的孩子来你家送柴，站在门口不敢进来。', '你家仓里堆着往年的陈粮。年景不好的时候，别人家来借，父亲总要先算一算利息。', '你骑在家里的牛背上，看佃客们插秧。', '你生病时，家里请了城里的医者来，熬药的陶罐在灶上咕嘟了好几天。', '母亲带着你去拜祭祖墓，墓前新立了一对石阙。'],
      top: ['你身边有乳母，还有两个专门伺候你的小僮。', '族中祭祖，几百口人列在祠堂前。你跟着父兄行礼，一动也不敢动。', '家里宴客，堂上鼓瑟吹笙。你被叫出来给客人行礼，背了一段《诗》。', '你的衣服是锦做的，袖口绣着云纹。洗衣的婢女说，一件衣服抵得上她一家一年的口粮。', '父亲的门生故吏来拜年，车马在门外排了很长的队。', '冬天，你屋里生着炭盆，挂着厚帘，外面下着大雪。', '庄园里有自己的铁匠、木匠、织坊和酒坊，什么都不用出门去买。', '你在庄园里骑小马，一个小僮牵着缰绳跟着跑，跑得满头大汗。']
    },
    childF: {
      low: ['你八岁就开始帮母亲给大户人家纺线，一天要纺完一斤麻才能吃饭。', '你背着更小的弟妹下地，母亲在前面锄草。', '你跟着母亲去河边洗别人家的衣服，换几把米。'],
      mid: ['母亲教你织布。你织出的第一匹布歪歪扭扭，母亲还是拿去集上卖了。', '你学会了腌菜、酿醋，母亲说这样将来嫁出去不会被人笑话。'],
      high: ['母亲开始教你女红，说将来要嫁到门当户对的人家去。', '你跟着家里的先生认了些字。父亲说，女孩子认得几个字就够了。'],
      top: ['你开始读班昭的《女诫》：“卑弱第一”。保姆说，这是做一个好女子的头一课。', '家里请了女师教你礼仪：如何行礼，如何进退，如何不笑出声。', '你学着弹琴。手指按不住弦，女师就让你从早练到晚。']
    },
    adult: {
      low: ['你给田主家扛了一天活，换回半斗糠。', '你把家里最后一只鸡卖了，换钱交算赋。', '粮缸见了底。你一天只吃一顿，省下来给家里的小的。', '下雨天屋顶漏水，一家人挤在不漏的那个角落里坐到天亮。', '你向田主家借了种子，秋后要加倍还。', '你们一家的衣服凑起来，不够每人一身。出门的人穿，在家的人就裹着草席。', '你在集上看了半天那把新铁锄，最后还是没买。'],
      mid: ['今年交完租税，还剩下几斛余粮。你把它藏进地窖，以防荒年。', '你攒了几年钱，给家里添了一口铁釜。', '你家养了一头猪，年底卖了钱，正好交口赋。', '亲戚来借粮，你家借给他两斛，没有要利息。', '年景平平。日子不宽裕，可也饿不着。'],
      high: ['农忙时你家雇了几个短工。你在田头看着，自己不怎么下地了。', '你家放出去的债，今年收回了大半。还不上的那几家，拿田契来抵。', '你家添了一辆牛车，进城不用再走路了。', '县里的小吏来催赋，你请他喝了一顿酒。他走的时候，态度客气了许多。'],
      top: ['你家庄园里，佃客、部曲、僮仆加起来有上百口人。你连一半的名字都叫不出。', '你出门有车，车后跟着骑马的宾客。路上的行人纷纷避到道旁。', '家里办了一场宴会，花掉的钱，够一户农家吃上三年。']
    }
  };

  // 幼年一次性的事（不需要选择）：tiers 档位，age 年龄，sex 性别，fx 效果，fn 特殊处理
